#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    if (n <= 0) {
        return 0;
    }

    int64_t *arr = (int64_t *)malloc((size_t)n * sizeof(int64_t));
    if (arr == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%lld", (long long *)&arr[i]) != 1) {
            free(arr);
            return 1;
        }
    }

    // Simple insertion sort for small n (up to 1000)
    for (int i = 1; i < n; i++) {
        int64_t key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }

    for (int i = 0; i < n; i++) {
        printf("%lld\n", (long long)arr[i]);
    }

    free(arr);
    return 0;
}
