            for (int64_t j = i * i; j <= n; j += i) {
                is_prime[j] = 0;
            }
        }
    }

    int64_t count = 0;
    for (int64_t i = 2; i <= n; i++) {
        if (is_prime[i]) {
            count++;
        }
    }

    printf("%lld\n", count);

    free(is_prime);
    return 0;
